// Entrada: { key }. Salida: { key, seen }. Solo para envios directos (SMTP/Telegram) que no pasan por Idempotency-Key.
const sd = $getWorkflowStaticData('global');
sd.keys ??= [];
const out = [];
for (const item of $input.all()) {
  const key = String(item.json.key);
  const seen = sd.keys.some((k) => k.k === key);
  if (!seen) { sd.keys.push({ k: key, t: Date.now() }); if (sd.keys.length > 2000) sd.keys.splice(0, sd.keys.length - 2000); }
  out.push({ json: { key, seen } });
}
return out;
